using System.Text.Json;

namespace MyApp.Evals.Tests;

public sealed record GoldenItem(
    string Id,
    string UserMessage,
    string? ReferenceResponse,
    string? Context,
    string[]? ExpectedTraits,
    string[]? ExpectedToolCalls);

internal sealed record GoldenRoot(int SchemaVersion, List<GoldenItem> Scenarios);

internal static class GoldenLoader
{
    private static readonly JsonSerializerOptions s_options = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower,
        PropertyNameCaseInsensitive = true,
    };

    public static List<GoldenItem> Load()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "Quality", "golden.json");
        var root = JsonSerializer.Deserialize<GoldenRoot>(
            File.ReadAllText(path), s_options);
        return root?.Scenarios ?? new();
    }
}

internal static class RubricLoader
{
    public static string SystemPrompt()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "Quality", "rubric.md");
        return File.Exists(path) ? File.ReadAllText(path) : "You are a helpful assistant.";
    }
}

internal static class Thresholds
{
    private static readonly JsonSerializerOptions s_options = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower,
        PropertyNameCaseInsensitive = true,
    };

    private static ThresholdsRoot? s_root;

    private static ThresholdsRoot Root => s_root ??= LoadRoot();

    private static ThresholdsRoot LoadRoot()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "quality.thresholds.json");
        if (!File.Exists(path)) return new ThresholdsRoot(2, false, new());
        return JsonSerializer.Deserialize<ThresholdsRoot>(
            File.ReadAllText(path), s_options) ?? new ThresholdsRoot(2, false, new());
    }

    public static void ApplyOrLog(EvaluationResult result, string scenarioId)
    {
        // When hard_fail is false, thresholds are informational only
        if (!Root.HardFail) return;

        foreach (var (metricName, threshold) in Root.Thresholds)
        {
            var metric = result.Metrics.FirstOrDefault(m => m.Key == metricName);
            if (metric.Value is NumericMetric nm && threshold.MinValue.HasValue)
            {
                if (nm.Value < threshold.MinValue.Value)
                    Assert.Fail($"[{scenarioId}] {metricName} = {nm.Value}, below min {threshold.MinValue.Value}");
            }
        }
    }
}

internal sealed record ThresholdsRoot(int SchemaVersion, bool HardFail, Dictionary<string, ThresholdEntry> Thresholds);
internal sealed record ThresholdEntry(string? MinRating = null, decimal? MinValue = null, decimal? MaxValue = null);

