public static IChatClient Create()
{
    var builder = Host.CreateApplicationBuilder();

    // In test hosts, user-secrets are NOT auto-loaded. Add explicitly.
    builder.Configuration.AddUserSecrets(typeof(AgentChatClientFactory).Assembly, optional: true);

    // Mirror the AppHost registration: AddAzureOpenAIChatClient("chat", "gpt-4o-mini")
    // Reads ConnectionStrings:chat from configuration.
    var connectionString = builder.Configuration.GetConnectionString("chat");
    if (string.IsNullOrEmpty(connectionString))
    {
        throw new InvalidOperationException(
            "EVAL_USE_REAL_AGENT=1 but IChatClient could not be resolved. " +
            "The detected registration reads connection string \"chat\" from configuration. " +
            "Aspire's AppHost populates this at runtime, but `dotnet test` runs standalone. " +
            "Wire one of:\n" +
            "  dotnet user-secrets set \"ConnectionStrings:chat\" " +
            "\"Endpoint=https://<host>.services.ai.azure.com/models;Key=<key>;DeploymentId=chat\" --project MyApp.Evals.Tests\n" +
            "  # Or Entra-ID auth (no Key= segment):\n" +
            "  dotnet user-secrets set \"ConnectionStrings:chat\" " +
            "\"Endpoint=https://<host>.services.ai.azure.com/models;DeploymentId=chat\" --project MyApp.Evals.Tests");
    }

    // Parse connection string and build an OpenAI-compatible IChatClient
    var parts = connectionString.Split(';')
        .Select(p => p.Split('=', 2))
        .Where(p => p.Length == 2)
        .ToDictionary(p => p[0].Trim(), p => p[1].Trim(), StringComparer.OrdinalIgnoreCase);

    parts.TryGetValue("Endpoint", out var endpoint);
    parts.TryGetValue("Key", out var key);
    parts.TryGetValue("DeploymentId", out var deploymentId);

    var clientBuilder = new ChatClientBuilder()
        .UseFunctionInvocation();

    // Use the MEAI OpenAI integration
    return new Azure.AI.OpenAI.AzureOpenAIClient(
        new Uri(endpoint ?? "https://placeholder.openai.azure.com"),
        new System.ClientModel.ApiKeyCredential(key ?? "placeholder"))
        .GetChatClient(deploymentId ?? "chat")
        .AsIChatClient();
}

